<template>
  <q-chip
    :size="size"
    dense
    :class="['assignee-chip', { 'assignee-chip--unassigned': !name }]"
  >
    <q-avatar
      :icon="avatarIcon"
      :color="avatarColor"
      text-color="white"
      :size="avatarSize"
      class="assignee-chip__avatar"
    />
    <span class="assignee-chip__name">{{ displayName }}</span>
  </q-chip>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export default defineComponent({
  name: 'AssigneeChip',
  props: {
    name: {
      type: String,
      default: '',
    },
    type: {
      type: String as PropType<'human' | 'agent'>,
      default: 'human',
    },
    size: {
      type: String as PropType<'sm' | 'md'>,
      default: 'sm',
    },
  },
  computed: {
    displayName(): string {
      return this.name || 'Unassigned';
    },
    avatarIcon(): string {
      return this.type === 'agent' ? 'smart_toy' : 'person';
    },
    avatarColor(): string {
      if (!this.name) return 'grey-5';
      return this.type === 'agent' ? 'primary' : 'blue-grey-6';
    },
    avatarSize(): string {
      return this.size === 'md' ? '24px' : '20px';
    },
  },
});
</script>

<style scoped lang="scss">
.assignee-chip {
  background: var(--dashboard-status-background);
  color: var(--dashboard-text-color);
  border: none;

  &--unassigned {
    opacity: 0.6;
  }

  &__avatar {
    margin-right: 4px;
  }

  &__name {
    font-size: 12px;
    line-height: 1;
  }
}

